import { readFileSync } from 'node:fs';
import vm from 'node:vm';

const scriptSrc = readFileSync('/tmp/page-script.js', 'utf8');

function makeEl(tag) {
  return {
    tag,
    className: '',
    textContent: '',
    hidden: false,
    dateTime: '',
    children: [],
    append(...kids) { this.children.push(...kids); },
    replaceChildren(...kids) { this.children = [...kids]; },
  };
}

function defer() {
  let resolve, reject;
  const promise = new Promise((res, rej) => { resolve = res; reject = rej; });
  return { promise, resolve, reject };
}

const tick = () => new Promise((r) => setTimeout(r, 0));

function newPage() {
  const els = {};
  for (const id of ['idea-form', 'f-title', 'f-desc', 'f-scenario', 'error', 'success', 'empty', 'ideas']) {
    els[id] = makeEl(id);
  }
  els['f-title'].value = '';
  els['f-desc'].value = '';
  els['f-scenario'].value = '';
  const listeners = {};
  els['idea-form'].addEventListener = (ev, fn) => { listeners[ev] = fn; };
  els['idea-form'].reset = () => {
    els['f-title'].value = '';
    els['f-desc'].value = '';
    els['f-scenario'].value = '';
  };
  const pending = [];
  const sandbox = {
    console,
    Set,
    document: {
      getElementById: (id) => els[id],
      createElement: (tag) => makeEl(tag),
    },
    fetch: (url, opts) => {
      const d = defer();
      pending.push({ url, opts, d });
      return d.promise;
    },
  };
  vm.createContext(sandbox);
  vm.runInContext(scriptSrc, sandbox);
  return {
    els, listeners, pending,
    respond(body) {
      const req = pending.shift();
      req.d.resolve({ ok: true, json: async () => body });
    },
    respondMethod(method, body, ok = true) {
      const idx = pending.findIndex((p) => !p.opts === (method === 'GET'));
      const [req] = pending.splice(idx, 1);
      req.d.resolve({ ok, json: async () => body });
    },
    failMethod(method) {
      const idx = pending.findIndex((p) => !p.opts === (method === 'GET'));
      const [req] = pending.splice(idx, 1);
      req.d.reject(new Error('network down'));
    },
    async submit({ title = '标题', description = '说明内容', scenario = '' } = {}) {
      els['f-title'].value = title;
      els['f-desc'].value = description;
      els['f-scenario'].value = scenario;
      listeners.submit({ preventDefault() {} });
      await tick(); await tick();
    },
  };
}

const idea = (id, title = id, extra = {}) => ({
  id, title, description: 'desc-' + id, scenario: '', createdAt: '2026-10-03T00:00:00.000Z', ...extra,
});
const titles = (page) => page.els.ideas.children.map((c) => c.children[0].textContent);
let passed = 0;
function check(name, cond, detail) {
  if (!cond) { console.error('FAIL:', name, detail ?? ''); process.exitCode = 1; }
  else { passed++; console.log('PASS:', name); }
}

// 1. POST succeeds first, later GET contains the same idea (dedupe by id) + an older one
{
  const page = newPage();
  const A = idea('a', '新意见');
  const B = idea('b', '旧意见');
  await page.submit({ title: '新意见', description: '说明内容' });
  page.respondMethod('POST', { idea: A });
  await tick();
  page.respondMethod('GET', { ideas: [A, B] });
  await tick();
  check('1 提交先到、列表后到且含同一条：按 id 只展示一份，顺序最新在前',
    JSON.stringify(titles(page)) === JSON.stringify(['新意见', '旧意见']),
    JSON.stringify(titles(page)));
  check('1 空列表提示隐藏', page.els.empty.hidden === true);
  check('1 成功提示仍在', page.els.success.hidden === false && page.els.success.textContent.includes('已保存'));
}

// 2. GET was taken before the POST: empty list arrives late, submitted idea must stay
{
  const page = newPage();
  await page.submit({ title: '唯一意见', description: '说明内容' });
  page.respondMethod('POST', { idea: idea('a', '唯一意见') });
  await tick();
  page.respondMethod('GET', { ideas: [] });
  await tick();
  check('2 迟到的空列表不能清掉已保存意见', JSON.stringify(titles(page)) === JSON.stringify(['唯一意见']),
    JSON.stringify(titles(page)));
  check('2 已有意见时不显示空提示', page.els.empty.hidden === true);
}

// 3. GET fails after a successful POST: new idea visible, load failure stated separately
{
  const page = newPage();
  await page.submit({ title: '新意见', description: '说明内容' });
  page.respondMethod('POST', { idea: idea('a', '新意见') });
  await tick();
  page.failMethod('GET');
  await tick();
  check('3 列表加载失败时新意见仍可见', JSON.stringify(titles(page)) === JSON.stringify(['新意见']),
    JSON.stringify(titles(page)));
  check('3 显示加载失败文案并保留刷新重试提示',
    page.els.empty.hidden === false && page.els.empty.textContent.includes('加载失败') && page.els.empty.textContent.includes('刷新重试'),
    page.els.empty.textContent);
  check('3 成功提示仍说明已保存，未被说成提交失败',
    page.els.success.hidden === false && page.els.success.textContent.includes('已保存') && page.els.error.hidden === true);
}

// 4. GET arrives first (snapshot without the new idea), then POST succeeds
{
  const page = newPage();
  await page.submit({ title: '新意见', description: '说明内容' });
  page.respondMethod('GET', { ideas: [idea('b', '旧意见')] });
  await tick();
  check('4a 提交结果到达前先显示已有意见', JSON.stringify(titles(page)) === JSON.stringify(['旧意见']));
  page.respondMethod('POST', { idea: idea('a', '新意见') });
  await tick();
  check('4b 提交成功后新意见在最前、旧意见保留', JSON.stringify(titles(page)) === JSON.stringify(['新意见', '旧意见']),
    JSON.stringify(titles(page)));
}

// 5. POST itself fails: no optimistic row, form content kept, error shown
{
  const page = newPage();
  await page.submit({ title: '待提交', description: '写好的说明' });
  page.failMethod('POST');
  await tick();
  check('5a 提交失败不向列表加入未确认意见', page.els.ideas.children.length === 0);
  check('5b 提交失败显示原有网络错误', page.els.error.hidden === false && page.els.error.textContent.includes('提交未成功'));
  check('5c 表单内容保留', page.els['f-title'].value === '待提交' && page.els['f-desc'].value === '写好的说明');
  page.respondMethod('GET', { ideas: [idea('b', '旧意见')] });
  await tick();
  check('5d 之后列表正常到达只显示服务端记录', JSON.stringify(titles(page)) === JSON.stringify(['旧意见']));
}

// 6. No submission, GET returns empty: original empty prompt, only after success
{
  const page = newPage();
  await tick();
  check('6a 加载中不误报空列表', page.els.empty.hidden === true);
  page.respondMethod('GET', { ideas: [] });
  await tick();
  check('6b 加载成功且确实为空才显示原空提示',
    page.els.empty.hidden === false && page.els.empty.textContent === '还没有意见记录。',
    page.els.empty.textContent);
}

// 7. GET fails immediately, no submission: load-failure message
{
  const page = newPage();
  page.failMethod('GET');
  await tick();
  check('7 首次列表失败显示加载失败提示',
    page.els.empty.hidden === false && page.els.empty.textContent.includes('意见列表加载失败'),
    page.els.empty.textContent);
}

// 8. Same title/description but distinct ids: both kept; same id only once
{
  const page = newPage();
  const mine = idea('a', '相同标题', { description: '相同说明' });
  await page.submit({ title: '相同标题', description: '相同说明' });
  page.respondMethod('POST', { idea: mine });
  await tick();
  page.respondMethod('GET', {
    ideas: [
      idea('a', '相同标题', { description: '相同说明' }),
