  await tick();
  check('8 同 id 去重、不同 id 即使内容相同也各自保留',
    JSON.stringify(titles(page)) === JSON.stringify(['相同标题', '相同标题', '另一标题']),
    JSON.stringify(titles(page)));
}

// 9. Normal flow: load fully completes first, then submit (original behavior preserved)
{
  const page = newPage();
